import { previewAccountLiquidation, sellAccountToSdgnrs, liquidationUnavailableReason } from '../app/account-liquidation.js';
import { get, subscribe, deriveCanSign } from '../app/store.js';
import { displayEthCompact } from '../app/scaling.js';
import { compactUiError } from '../app/ui-error.js';
import { openPanelPopup, closePanelPopup } from '../app/panel-popups.js';

let active = null;
export function closeAccountLiquidation() { closePanelPopup('liquidation', { restoreFocus: false }); }

export function openAccountLiquidation({ player, trigger, onSold, onClose } = {}) {
  closeAccountLiquidation();
  const panel = document.createElement('section');
  panel.className = 'panel-popup liquidation-popup';
  panel.id = 'panel-liquidation';
  panel.dataset.panelPopup = 'liquidation';
  panel.hidden = true;
  panel.setAttribute('role', 'dialog'); panel.setAttribute('aria-modal', 'true');
  panel.setAttribute('aria-labelledby', 'liquidation-title');
  panel.innerHTML = `
    <div class="panel-popup__window">
      <header class="panel-popup__header">
        <h2 id="liquidation-title">LIQUIDATE ACCOUNT</h2>
        <button type="button" class="panel-popup__close" data-panel-close aria-label="Close liquidation">×</button>
      </header>
      <div class="panel-popup__body">
        <div class="liquidation-quote" data-bind="liquidation-quote" hidden>
          <span>YOU RECEIVE</span><strong data-bind="liquidation-price">—</strong>
          <p class="liquidation-warning">All game assets and your wallet’s native sDGNRS will be permanently lost in exchange for <span data-bind="liquidation-exchange">this amount</span>.</p>
        </div>
        <p data-bind="liquidation-status" role="status" aria-live="polite"></p>
        <label class="liquidation-consent"><input type="checkbox" data-bind="liquidation-consent">
          <span>I understand this is permanent.</span></label>
        <div class="liquidation-actions">
          <button type="button" data-bind="liquidation-refresh">Refresh quote</button>
          <button type="button" data-bind="liquidation-sell" disabled>Liquidate account</button>
        </div>
      </div>
    </div>`;
  document.body.appendChild(panel);
  const node = name => panel.querySelector(`[data-bind="liquidation-${name}"]`);
  const consent = node('consent'), sell = node('sell'), refresh = node('refresh');
  let quote = null, loading = false, busy = false, closed = false, sequence = 0, sold = false;
  const cleanups = [];
  const ownerCanSell = () => deriveCanSign() && get('ui.mode') === 'self'
    && String(get('connected.address')).toLowerCase() === String(player).toLowerCase()
    && quote?.payee === String(player).toLowerCase();
  const status = (message, error = false) => {
    node('status').textContent = message;
    node('status').hidden = !message;
    node('status').classList.toggle('is-error', error);
  };
  const sync = () => {
    const available = quote && !liquidationUnavailableReason(quote);
    sell.disabled = loading || busy || sold || !available || !ownerCanSell() || !consent.checked;
    consent.disabled = loading || busy || sold || !available || !ownerCanSell();
    refresh.disabled = loading || busy || sold;
    sell.textContent = busy ? 'Confirming…' : sold ? 'Account sold' : 'Liquidate account';
  };
  const load = async () => {
    const seq = ++sequence;
    loading = true; quote = null; consent.checked = false;
    node('quote').hidden = true; status('Loading the current liquidation offer…'); sync();
    try {
      const result = await previewAccountLiquidation({ player });
      if (closed || seq !== sequence) return;
      quote = result;
      if (quote.price > 0n) {
        node('quote').hidden = false;
        const amount = `${displayEthCompact(quote.price, 18)} ETH`;
        node('price').textContent = amount;
        node('exchange').textContent = amount;
      }
      status(liquidationUnavailableReason(quote) || (ownerCanSell()
        ? ''
        : 'Connect the owner wallet to sell this account. Operators cannot liquidate.'));
    } catch (error) {
      if (!closed && seq === sequence) status(compactUiError(error, 'Could not load the offer. Refresh to try again.'), true);
    } finally { if (!closed && seq === sequence) { loading = false; sync(); } }
  };
  consent.addEventListener('change', sync);
  refresh.addEventListener('click', () => { if (!refresh.disabled) void load(); });
  sell.addEventListener('click', async () => {
    if (sell.disabled || busy) return;
    busy = true; status('Confirm the account sale in your wallet…'); sync();
    try {
      const result = await sellAccountToSdgnrs({ player, accountId: quote.accountId, minEthOut: quote.price });
      sold = true;
      if (!closed) status('Account sold. The ETH payout was sent to your wallet.');
      // Refresh failures cannot turn a mined sale into a displayed transaction failure.
      try { await onSold?.(result); } catch { /* the next regular poll will retry */ }
    } catch (error) {
      if (!closed) { quote = null; consent.checked = false; status(compactUiError(error, 'Sale did not complete. Refresh the quote to try again.'), true); }
    } finally { busy = false; if (!closed) sync(); }
  });
  panel.addEventListener('app:panel-close', () => {
    if (closed) return;
    closed = true; sequence++;
    cleanups.forEach(unsubscribe => unsubscribe());
    panel.remove();
    if (active === panel) active = null;
    onClose?.();
  });
  for (const path of ['connected.address', 'viewing.address', 'ui.mode']) {
    cleanups.push(subscribe(path, () => { if (active === panel) closeAccountLiquidation(); }));
  }
  cleanups.push(subscribe('ui.chainOk', sync));
  active = panel;
  openPanelPopup('liquidation', trigger, panel);
  void load();
}
